        if not f.get(req): bad.append(('FM',f.get('name'),req))
for r in d['skill_rules']:
    for req in ('rule_id','rule','because','because_source','evidence','taught_or_enforced','skill_target','overlap','feasibility'):
        if not r.get(req): bad.append(('SR',r.get('rule_id'),req))
    if r['because_source']=='user-verbatim' and not r.get('quote'): bad.append(('SR',r['rule_id'],'quote'))
for p in d['philosophy']:
    if p['source']=='user-verbatim' and not p.get('quote'): bad.append(('PH',p['loc'],'quote'))
for p in d['pairing_rules']:
    for req in ('rule_id','rule','class','because','because_source','evidence'):
        if not p.get(req): bad.append(('PR',p.get('rule_id'),req))
    if p['because_source']=='user-verbatim' and not p.get('quote'): bad.append(('PR',p['rule_id'],'quote'))
for c in d['council_episodes']:
    for req in ('loc','trigger','invoked_by','personas','voices','outcome','fidelity','user_reaction','lesson'):
        if req not in c or c.get(req) in (None,''): bad.append(('CE',c.get('loc'),req))
print('VIOLATIONS:',bad)
print({k:(len(v) if isinstance(v,list) else v) for k,v in d.items()} if False else 'ok')
for k,v in d.items():
    if isinstance(v,list): print(k,len(v))
